UPDATE services SET data=json_set(data,'$.description','Kompaniyangiz, xizmatlaringiz yoki mahsulotlaringiz uchun sayt yaratamiz. Sahifalar, dizayn va kerakli funksiyalarni siz bilan kelishib, saytni ishga tushiramiz.'),updated_at=CURRENT_TIMESTAMP WHERE slug='veb-sayt' AND json_extract(data,'$.description')='Biznesingizni internetda tanishtiradigan tez va tushunarli sayt. Matn tuzilishi, dizayn, dasturlash va domenga ulashgacha o‘zimiz bajaramiz.';
