UPDATE services SET data=json_set(data,'$.description','Buyurtma qabul qilish, mijozlarni qabulga yozish yoki savollarga javob berish uchun bot yaratamiz. Katalog va savat kerak bo‘lsa, Telegram ichida ochiladigan ilova tayyorlaymiz.'),updated_at=CURRENT_TIMESTAMP WHERE slug='telegram-bot' AND json_extract(data,'$.description')='Mijozlaringiz allaqachon Telegram’da. Buyurtma qabul qiladigan, savollarga javob beradigan va sizga xabar yuboradigan bot yasaymiz. Kattaroq vazifa uchun — Telegram ichida ochiladigan to‘liq ilova (Mini App).';
