UPDATE services SET data=json_set(data,'$.description','Sayt, bot yoki ilovangizga to‘lov, SMS va boshqa xizmatlarni ulaymiz. Buyurtma hamda mahsulot ma’lumotlarini mavjud hisob tizimingiz bilan bog‘laymiz.'),updated_at=CURRENT_TIMESTAMP WHERE slug='integratsiyalar' AND json_extract(data,'$.description')='Mijoz saytda yoki botda to‘laydi, buyurtma CRM’ga tushadi, mijozga SMS boradi, sizga Telegram’da xabar keladi — hech narsani qo‘lda ko‘chirmaysiz. Boshqalar yasagan saytga ham ulaymiz.';
